-- 20261125003137 ascent_prioritize_unused_word_vocabulary
do $patch$
declare d text;n text;
begin
select pg_get_functiondef('ascent_game.generate_varied_climb(text,uuid)'::regprocedure) into d;
n:=replace(d,'   ), overall as (','   ), clue_usage as (
    select clue,count(*) n from ascent_game.runs r join ascent_game.circuits c on c.route_id=case when r.scope like ''practice:%'' then r.scope else ''daily:''||to_char(r.day,''YYYY-MM-DD'') end cross join lateral jsonb_array_elements(c.boards) p cross join lateral jsonb_array_elements_text(p->''clues'') clue where r.ticket=player and c.route_id<>seed group by 1
   ), overall as (');
n:=replace(n,'(b.phrase_count<>required_phrases),coalesce(u.n,0),(select count(*) from unnest(b.clues) c where c=any(prior_clues)),h.last_seen nulls first','(b.phrase_count<>required_phrases),(select count(*) from unnest(b.clues) c where c=any(prior_clues)),coalesce(u.n,0),(select coalesce(sum(cu.n),0) from unnest(b.clues) as cl(word) join clue_usage cu on cu.clue=cl.word),h.last_seen nulls first');
if n=d or n not like '%join clue_usage cu%' then raise exception 'Novelty patch mismatch';end if;execute n;
end;$patch$;